// Paso 1: predice el orden y luego ejecútalo.
// Escribe los cuatro console.log para que salga: 1, 4, 3, 2

console.log('todavía nada');

// Un almacén que tarda en contestar, como cualquier base de datos.
// La versión de callbacks es la que había antes de las promesas.

const DATOS = { 1: 'Ada', 2: 'Grace' };

function buscarCallback(id, callback) {
  setTimeout(function () {
    const nombre = DATOS[id];
    if (!nombre) {
      callback(new Error('No existe el usuario ' + id));
      return;
    }
    callback(null, nombre);
  }, 10);
}

module.exports = { buscarCallback };

