const { buscarCallback } = require('./usuarios');

buscarCallback(1, function (error, nombre) {
  if (error) {
    console.log(error.message);
    return;
  }
  console.log(nombre);

  buscarCallback(2, function (error2, nombre2) {
    if (error2) {
      console.log(error2.message);
      return;
    }
    console.log(nombre2);

    buscarCallback(99, function (error3, nombre3) {
      if (error3) {
        console.log(error3.message);
        return;
      }
      console.log(nombre3);
    });
  });
});

body.es:
Una promesa es la misma espera con otra forma: en vez de pasar qué hacer después, se devuelve un objeto que **representa el resultado futuro**. Convertir un callback en promesa es envolverlo:

```js
function leerAsync(ruta) {
  return new Promise((ok, falla) => {
    leer(ruta, (fallo, datos) => (fallo ? falla(fallo) : ok(datos)));
  });
}
```

Eso es exactamente lo que hace `util.promisify` en Node, y por eso `fs.promises` existe: es la misma API envuelta una vez por todas.

Lo que se gana no es estética. Con `async/await` el código vuelve a leerse de arriba abajo, **un solo `try/catch` cubre toda la cadena** —en vez de un `if (error)` por nivel— y los errores se propagan solos hasta quien pueda hacer algo con ellos, igual que en código síncrono.

La trampa que queda: `await` **solo** funciona dentro de una función `async`, y olvidarlo no da error de sintaxis en el sitio equivocado sino una promesa sin resolver que se imprime como `Promise { <pending> }`.

**Escribe `buscar(id)` en `main.js` envolviendo `buscarCallback`, y repite la misma secuencia con `async/await` y un solo `try/catch`.**

body.en:
A promise is the same wait in another shape: instead of passing what to do next, you return an object that **represents the future result**. Turning a callback into a promise means wrapping it:

```js
function leerAsync(ruta) {
  return new Promise((ok, falla) => {
    leer(ruta, (fallo, datos) => (fallo ? falla(fallo) : ok(datos)));
  });
}
```

That's exactly what `util.promisify` does in Node, and why `fs.promises` exists: the same API wrapped once and for all.

What you gain isn't aesthetics. With `async/await` the code reads top to bottom again, **a single `try/catch` covers the whole chain** — instead of one `if (error)` per level — and errors propagate on their own up to whoever can do something about them, just like in synchronous code.

The remaining trap: `await` **only** works inside an `async` function, and forgetting it doesn't give you a syntax error in the right place but an unresolved promise that prints as `Promise { <pending> }`.

**Write `buscar(id)` in `main.js` wrapping `buscarCallback`, and repeat the same sequence with `async/await` and a single `try/catch`.**

solution.content:
const { buscarCallback } = require('./usuarios');

function buscar(id) {
  return new Promise(function (resolver, rechazar) {
    buscarCallback(id, function (error, nombre) {
      if (error) rechazar(error);
      else resolver(nombre);
    });
  });
}

async function principal() {
  try {
    console.log(await buscar(1));
    console.log(await buscar(2));
    console.log(await buscar(99));
  } catch (error) {
    console.log(error.message);
  }
}

principal();

